const datos = $input.first().json || {};
const ejecucion = datos.execution || {};
const flujo = datos.workflow || {};
const error = ejecucion.error || {};

const mensaje = String(error.message || error.description || 'Sin mensaje de error');
const nodo = (error.node && error.node.name) || ejecucion.lastNodeExecuted || 'desconocido';

// Meta mete el código en el texto, en dos formatos que conviven:
//   "Fatal -1/2207032"                 (código y subcódigo juntos)
//   "Error: (#25) ... (code 25, subcode 2207050)"
// No hay campo estructurado, así que se leen los dos y se prefiere el primero.
const pareja = mensaje.match(/(-?\d+)\s*\/\s*(\d+)/);
const suelto = mensaje.match(/\(code\s+(-?\d+)/i);
const subSuelto = mensaje.match(/subcode\s+(\d+)/i);
const codigo = pareja ? Number(pareja[1]) : suelto ? Number(suelto[1]) : null;
const subcodigo = pareja ? Number(pareja[2]) : subSuelto ? Number(subSuelto[1]) : null;

const TRANSIENTES = [
  [-1, 2207001],
  [-1, 2207032],
  [-2, 2207003],
  [24, 2207008],
];
const LIMITE_DIARIO = 9;
const CUENTA_RESTRINGIDA = [25, 2207050];
const SPAM = [4, 2207051];
const TOKEN = 190;
const PERMISOS = [10, 200];
const LLAMADAS = [4, 17, 32, 613];
const HIJOS = 2207028;

const esTransitorio = TRANSIENTES.some(([c, s]) => codigo === c && subcodigo === s);
const esRed = /ECONNREFUSED|ETIMEDOUT|ENOTFOUND|getaddrinfo|socket hang up|EAI_AGAIN/i.test(mensaje);
// Los nodos nuestros lanzan en castellano y sin código de Meta. Se reconocen por
// lo que dicen, que es justo lo que hay que enseñar en el correo.
const esPaquete = /planes|diapositivas|pie|etiquetas|menciones|carrusel|hijos|historia|cupo/i.test(mensaje) && codigo === null;

let clase = 'desconocido';
let gravedad = 'alta';
let queHacer = 'Abre la ejecución, mira el nodo que falló y decide si se puede repetir hoy.';

if (esTransitorio) {
  clase = 'transitorio';
  gravedad = 'baja';
  queHacer =
    'Es un fallo pasajero de Meta (un contenedor que tarda, una lectura que no llega). ' +
    'Ejecuta el flujo a mano para publicar hoy; no hace falta tocar nada más.';
} else if (codigo === CUENTA_RESTRINGIDA[0] && subcodigo === CUENTA_RESTRINGIDA[1]) {
  clase = 'cuenta restringida';
  queHacer =
    'Meta ha restringido la cuenta para publicar. Entra en la app de Instagram, Calidad de la cuenta, ' +
    'y revisa el aviso. No se arregla reintentando.';
} else if (codigo === SPAM[0] && subcodigo === SPAM[1]) {
  clase = 'marcado como spam';
  queHacer =
    'Meta ha marcado la acción como spam. No reintentes hoy: empeora. Espera 24 h y revisa ' +
    'que el flujo no esté publicando dos veces el mismo día.';
} else if (codigo === LIMITE_DIARIO) {
  clase = 'límite diario';
  gravedad = 'media';
  queHacer =
    'Se ha agotado el límite de publicaciones por API de las últimas 24 h. No es un fallo: ' +
    'espera a mañana. Si pasa dos días seguidos, algo está publicando de más.';
} else if (codigo === 2500 || (codigo === 200 && /valid app ID/i.test(mensaje))) {
  // 2500 es «no me has mandado token»: cabecera ausente, con otro nombre o con el
  // valor vacío. En /media el mismo problema sale como (#200) «Provide valid app ID».
  // No confundirlo con un token caducado, que da 190.
  clase = 'credencial sin token';
  queHacer =
    'Meta no ha recibido ninguna cabecera de autorización. Abre «Instagram · Huesca Hoy (Bearer)» ' +
    'y comprueba que el nombre es Authorization y que el valor empieza por "Bearer ". Si el valor ' +
    'está vacío o cortado, vuelve a pegar el token completo.';
} else if (codigo === TOKEN) {
  clase = 'token inválido o caducado';
  queHacer =
    'El token de Instagram ya no vale. Comprueba primero que el valor de la credencial empieza por ' +
    '"Bearer "; si ya lo hace, hay que regenerar el token en Meta y volver a guardarlo en ' +
    '«Instagram · Huesca Hoy (Bearer)». Hasta entonces no se publica nada.';
} else if (PERMISOS.includes(codigo)) {
  clase = 'permisos';
  queHacer =
    'La app no tiene permiso para esta llamada. Revisa en Meta que siga con ' +
    'instagram_content_publish y que la cuenta siga vinculada a la página.';
} else if (LLAMADAS.includes(codigo)) {
  clase = 'demasiadas llamadas';
  gravedad = 'media';
  queHacer = 'Meta ha cortado por volumen de peticiones. Espera unos minutos y vuelve a ejecutar a mano.';
} else if (subcodigo === HIJOS) {
  clase = 'hijos del carrusel';
  queHacer =
    'El carrusel lleva un número de diapositivas que Meta no admite (2 a 20). Mira cuántas ' +
    'trae /api/promo y cuántas espera el flujo.';
} else if (esRed) {
  clase = 'red';
  gravedad = 'media';
  queHacer = 'No se pudo conectar. Comprueba que el sitio responde y vuelve a ejecutar a mano.';
} else if (esPaquete) {
  clase = 'paquete o cupo';
  queHacer =
    'El paquete no pasó la validación antes de tocar Meta, así que no se creó ningún contenedor. ' +
    'El mensaje dice qué regla se rompió; arréglalo en el repo y vuelve a ejecutar.';
}

const fecha = new Date();
const cuando = new Intl.DateTimeFormat('es-ES', {
  timeZone: 'Europe/Madrid',
  dateStyle: 'full',
  timeStyle: 'medium',
}).format(fecha);

const idEjecucion = ejecucion.id || '(sin id)';
const urlEjecucion =
  ejecucion.url ||
  (flujo.id ? 'https://n8n-n8n-0jf8jb-34e00a-217-154-101-13.sslip.io/workflow/' + flujo.id + '/executions/' + idEjecucion : '');

const codigoTexto = codigo === null ? 'sin código' : String(codigo) + (subcodigo === null ? '' : '/' + subcodigo);

const asunto =
  '[Huesca Hoy] ' +
  (gravedad === 'baja' ? 'Aviso' : gravedad === 'media' ? 'Fallo' : 'Fallo grave') +
  ': ' +
  clase +
  ' · ' +
  (flujo.name || 'flujo sin nombre');

const texto = [
  'El flujo «' + (flujo.name || 'sin nombre') + '» ha terminado en rojo.',
  '',
  'Cuándo:       ' + cuando,
  'Ejecución:    #' + idEjecucion + (urlEjecucion ? '  ' + urlEjecucion : ''),
  'Nodo:         ' + nodo,
  'Clase:        ' + clase + '  (' + codigoTexto + ')',
  '',
  'Lo que dijo el error:',
  '  ' + mensaje.replace(/\n/g, '\n  '),
  '',
  'Qué hacer:',
  '  ' + queHacer,
  '',
  '--',
  'Este aviso lo manda el flujo «Avisos · Huesca Hoy» de n8n.',
].join('\n');

return [{ json: { asunto, texto, clase, gravedad, nodo, codigo, subcodigo, idEjecucion } }];
